-- PT121-S4-Q6. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT121-S4-Q6$batch09$ AND q.stimulus=$batch09$In the first phase of the Industrial Revolution, machines were invented whose main advantage was that they worked faster than human workers. This technology became widely used because it was economically attractive; many unskilled workers could be replaced by just a few skilled workers. Today managers are looking for technology that will allow them to replace highly paid skilled workers with a smaller number of less-skilled workers.$batch09$ AND q.prompt=$batch09$The examples presented above best illustrate which one of the following propositions?$batch09$ AND q.correct_choice=$batch09$A$batch09$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT121-S4-Q6$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT121-S4-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$Early industrial machines replaced many unskilled workers with a few skilled ones, and that saved money. Today managers want technology that replaces highly paid skilled workers with fewer, less-skilled ones.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The two examples move in opposite directions on skill. Then it was unskilled to skilled, and now it's skilled to less skilled. So skill isn't the common thread. What's the same in both is fewer workers and lower labor costs. The first example even names the motive: the technology was "economically attractive."$batch09$), (2, $batch09$Goal$batch09$, $batch09$Employers adopt new technology because it cuts labor costs.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT121-S4-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Both examples swap expensive labor for cheaper labor: many workers for a few, highly paid workers for fewer, less-skilled ones. A names the motive behind both.$batch09$), ($batch09$B$batch09$, $batch09$Today's managers want to replace skilled workers with less-skilled ones. That doesn't suggest more education will keep workers competitive.$batch09$), ($batch09$C$batch09$, $batch09$This is the trap, picked by 15%. It picks up the modern example, where skilled workers may be replaced. But the first example shows skilled workers winning, so C can't be illustrated by both examples. And managers are only "looking for" this technology. We don't know skilled workers have already lost their advantage.$batch09$), ($batch09$D$batch09$, $batch09$Both examples cut the number of workers. Nothing says new jobs make up the difference.$batch09$), ($batch09$E$batch09$, $batch09$The passage never mentions heavy industry or says which industries are affected.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT121-S4-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
